import{_ as t,o,c as r,ag as e}from"./chunks/framework.CAXxHpAX.js";const d=JSON.parse('{"title":"自然务实","description":"","frontmatter":{},"headers":[],"relativePath":"10-核心模型/model-自然务实.md","filePath":"10-核心模型/model-自然务实.md","lastUpdated":1778031108000}'),l={name:"10-核心模型/model-自然务实.md"};function n(s,a,i,h,u,q){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="自然务实" tabindex="-1">自然务实 <a class="header-anchor" href="#自然务实" aria-label="Permalink to &quot;自然务实&quot;">​</a></h1><blockquote><p>了空居士智慧体系的方法论。 不要长篇大论，抓住核心，在生活中落实。</p></blockquote><hr><h2 id="核心内涵" tabindex="-1">核心内涵 <a class="header-anchor" href="#核心内涵" aria-label="Permalink to &quot;核心内涵&quot;">​</a></h2><p><strong>自然务实</strong> 是了空居士教导中最鲜明的风格特征。他反感繁琐的理论和教条式的修行，始终坚持——<strong>直指人心，抓核心，在生活中落实</strong>。</p><hr><h2 id="关键原子" tabindex="-1">关键原子 <a class="header-anchor" href="#关键原子" aria-label="Permalink to &quot;关键原子&quot;">​</a></h2><h3 id="_1-直指人心" tabindex="-1">1. 直指人心 <a class="header-anchor" href="#_1-直指人心" aria-label="Permalink to &quot;1. 直指人心&quot;">​</a></h3><p><strong>原文</strong>：我讲经只是讲它的含义和具体应用…直指人心来讲经典。</p><p><strong>解读</strong>：不绕圈子，不堆砌名相，不講学术性的繁复考证。了空居士的风格就像禅宗的直指人心——直接告诉你什么是核心，怎么用。</p><h3 id="_2-抓核心" tabindex="-1">2. 抓核心 <a class="header-anchor" href="#_2-抓核心" aria-label="Permalink to &quot;2. 抓核心&quot;">​</a></h3><p><strong>原文</strong>：我们将核心抓住，学起来就很快了。</p><p><strong>解读</strong>：学任何东西，先抓住最核心的那一点。《金刚经》的核心就是&quot;应无所住而生其心&quot;——《道德经》的核心就是&quot;无为而无不为&quot;。抓住核心，一通百通。</p><h3 id="_3-化繁为简" tabindex="-1">3. 化繁为简 <a class="header-anchor" href="#_3-化繁为简" aria-label="Permalink to &quot;3. 化繁为简&quot;">​</a></h3><p><strong>原文</strong>：《弟子规》一百多条，我概括成三方面：听话、有礼貌、好好学习。</p><p><strong>解读</strong>：不要背教条，不要被繁复的规则束缚。去掉多余的东西，留下最本质的几条，这就够了。</p><h3 id="_4-知行合一" tabindex="-1">4. 知行合一 <a class="header-anchor" href="#_4-知行合一" aria-label="Permalink to &quot;4. 知行合一&quot;">​</a></h3><p><strong>原文</strong>：读经是为了明理，明理是为了在工作生活中具体应用。</p><p><strong>解读</strong>：读书不是目的，用得上才是目的。了空居士从不鼓励&quot;读死书&quot;，学了要用，用了才真正学到。</p><h3 id="_5-生活即修行" tabindex="-1">5. 生活即修行 <a class="header-anchor" href="#_5-生活即修行" aria-label="Permalink to &quot;5. 生活即修行&quot;">​</a></h3><p><strong>原文</strong>：真正的修炼是在日常生活里。</p><p><strong>解读</strong>：六祖说&quot;佛法在世间，不离世间觉&quot;。修行不是躲在深山，也不是关在佛堂里诵经，而是在吃饭、工作、与人相处中修。</p><h3 id="_6-脚踏实地" tabindex="-1">6. 脚踏实地 <a class="header-anchor" href="#_6-脚踏实地" aria-label="Permalink to &quot;6. 脚踏实地&quot;">​</a></h3><p><strong>原文</strong>：务实不务虛，以真实贡献赢得尊重。</p><p><strong>解读</strong>：不要搞虚名假誉，一步一个脚印地走。道德经第三章讲的就是这个道理——不要追求虛名，要务实。</p><h3 id="_7-无为即无妄为" tabindex="-1">7. 无为即无妄为 <a class="header-anchor" href="#_7-无为即无妄为" aria-label="Permalink to &quot;7. 无为即无妄为&quot;">​</a></h3><p><strong>原文</strong>：无为就是按照客观实际情况去做。</p><p><strong>解读</strong>：无为不是什么都不做，<strong>是无妄为</strong>——没有私心妄想，按照实际情况该做就做，不该做就不做。</p><h3 id="_8-无为法而有差别" tabindex="-1">8. 无为法而有差别 <a class="header-anchor" href="#_8-无为法而有差别" aria-label="Permalink to &quot;8. 无为法而有差别&quot;">​</a></h3><p><strong>原文</strong>：一切贤圣皆以无为法而有差别。</p><p><strong>解读</strong>：所有圣贤做事都有一个共同点——不带主观成见，完全按照客观实际来具体问题具体分析。孔子对子路说&quot;要经长辈同意&quot;，对公西华说&quot;不用&quot;，这就是&quot;无为法&quot;——因材施教，没有固定套路。</p><h3 id="_9-攀缘vs随缘" tabindex="-1">9. 攀缘vs随缘 <a class="header-anchor" href="#_9-攀缘vs随缘" aria-label="Permalink to &quot;9. 攀缘vs随缘&quot;">​</a></h3><p><strong>原文</strong>：攀缘是一厢情愿的主观追求，随缘是按照客观因素去做最合理的方案。</p><p><strong>解读</strong>：很多修行人将&quot;随缘&quot;理解成&quot;随便&quot;，这是错的。随缘是实事求是的态度，不是不负责任。攀缘就是不管客观条件，一厢情愿地去追求。</p><h3 id="_10-无为习惯" tabindex="-1">10. 无为习惯 <a class="header-anchor" href="#_10-无为习惯" aria-label="Permalink to &quot;10. 无为习惯&quot;">​</a></h3><p><strong>原文</strong>：无私的奉献变成习惯了，就不用再提无私。</p><p><strong>解读</strong>：好习惯养成后，不需要刻意提醒自己。就像小时候父母教&quot;不能偷东西&quot;，长大后自然就不偷了。修行的最终目的是将善行变成习惯。</p><h3 id="_11-愿行合一" tabindex="-1">11. 愿行合一 <a class="header-anchor" href="#_11-愿行合一" aria-label="Permalink to &quot;11. 愿行合一&quot;">​</a></h3><p><strong>原文</strong>：发了愿就要去做，行动就圆满了愿。</p><p><strong>解读</strong>：光发愿不行动，愿就是妄语。修行人不要停留在&quot;发愿&quot;阶段，而是要落实到每一天的行动中。地藏菩萨&quot;地狱不空誓不成佛&quot;，他的行动本身就是在成佛。</p><h3 id="_12-布施的分寸" tabindex="-1">12. 布施的分寸 <a class="header-anchor" href="#_12-布施的分寸" aria-label="Permalink to &quot;12. 布施的分寸&quot;">​</a></h3><p><strong>原文</strong>：了解就多帮助，不了解就少帮助，这是最客观的。</p><p><strong>解读</strong>：帮助别人要量力而行，不是盲目慷慨。你了解一个人确实需要，给多一些；不了解，给少一些。这就是&quot;知之为知之，不知为不知&quot;——平等心不是&quot;一个价&quot;。</p><h3 id="_13-纯一直心" tabindex="-1">13. 纯一直心 <a class="header-anchor" href="#_13-纯一直心" aria-label="Permalink to &quot;13. 纯一直心&quot;">​</a></h3><p><strong>原文</strong>：纯一直心，不动道场。</p><p><strong>解读</strong>：潜意识、显意识一致，里表一致。做好事时，不是&quot;老师在耳边说应该做好事&quot;，而是自然而然地去做。从小受的教育已经内化为本能，做的时候没有多余的念头。</p><h3 id="_14-因上精进果上随缘" tabindex="-1">14. 因上精进果上随缘 <a class="header-anchor" href="#_14-因上精进果上随缘" aria-label="Permalink to &quot;14. 因上精进果上随缘&quot;">​</a></h3><p><strong>原文</strong>：因上精进，果上随缘就是中观。</p><p><strong>解读</strong>：做事时全力以赴，但对结果不执着。不是消极等待，也不是拼命抓取。该做的努力都做了，结果如何都能接受。这不是放弃，是智慧。</p><h3 id="_15-信解行证" tabindex="-1">15. 信解行证 <a class="header-anchor" href="#_15-信解行证" aria-label="Permalink to &quot;15. 信解行证&quot;">​</a></h3><p><strong>原文</strong>：信解行证——先相信，再理解，然后行动，最后证得。</p><p><strong>解读</strong>：学东西要四步走。第一步是&quot;信&quot;——相信这个道理是对的；第二步是&quot;解&quot;——理解清楚；第三步是&quot;行&quot;——去做；第四步是&quot;证&quot;——亲身体证。光信不解是迷信，光解不行是空谈。</p><h3 id="_16-经验不能照搬" tabindex="-1">16. 经验不能照搬 <a class="header-anchor" href="#_16-经验不能照搬" aria-label="Permalink to &quot;16. 经验不能照搬&quot;">​</a></h3><p><strong>原文</strong>：经验也只能借鉴参考，不能教条主义。</p><p><strong>解读</strong>：历史是一面镜子，但病万变药也要万变。孔子对子路说&quot;要经长辈同意&quot;，对公西华说&quot;不用&quot;——同样的道理，不同的人要不同对待。经验是参考，不是公式。</p><hr><hr><h2 id="实践指引" tabindex="-1">实践指引 <a class="header-anchor" href="#实践指引" aria-label="Permalink to &quot;实践指引&quot;">​</a></h2><p><strong>学习中</strong>：</p><ul><li>学任何道理，问自己：核心是什么？怎么用到生活中？</li><li>不追求&quot;学完&quot;，追求&quot;用上一条就赚一条&quot;</li><li>化繁为简，抓大放小</li></ul><p><strong>修行中</strong>：</p><ul><li>该念佛就念佛，该静坐就静坐，不要想太多&quot;怎么修才正确&quot;</li><li>修行就在日常生活里，吃饭吃饭，睡觉睡觉</li><li>&quot;做就是了&quot;——行动胜过千言万语</li></ul><hr><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 自然务实需要对境不住的支撑</li><li><a href="/10-核心模型/model-历境炼心">历境炼心</a> — 自然务实的具体实践</li></ul><h2 id="来源文章" tabindex="-1">来源文章 <a class="header-anchor" href="#来源文章" aria-label="Permalink to &quot;来源文章&quot;">​</a></h2><ul><li>金刚经第1分（法会因由分）</li><li>金刚经第2分（善现启请分）</li><li>金刚经第3分（大乘正宗分）</li><li>金刚经第4分（妙行无住分）</li><li>金刚经第5分（如理实见分）</li><li>金刚经第6分（正信希有分）</li><li>金刚经第7分（无得无说分）</li><li>金刚经第8分（依法出生分）</li><li>金刚经第9分（一相无相分）</li><li>道德经讲解</li><li>答疑专辑2014</li><li>早年论坛答疑</li></ul><blockquote><p>来源：<a href="/1了空居士讲《金刚经》-第一分法会因由分20160909">1了空居士讲《金刚经》-第一分法会因由分20160909</a>、<a href="/道德经讲解">道德经讲解</a> 蒸馏日期：2026-05-05（第一版）2026-05-05（第二版，新增5个原子）</p></blockquote>',68)])])}const g=t(l,[["render",n]]);export{d as __pageData,g as default};
